    while (fscanf(f, "%s %d %f", p.nombre, &amp;p.cantidad, &amp;p.precio) == 3) {
        printf("%-8s x%-4d @%.2f\n", p.nombre, p.cantidad, p.precio);
        total += p.cantidad * p.precio;
    }
